 $$('[data-path]').forEach(el=>el.oninput=()=>{setPath(el.dataset.path,el.value);if(/^(goal|context|criteria\.)/.test(el.dataset.path))state.cases.forEach(c=>c.human={});else if(/^cases\.\d+\.(input|output|reference|trace)$/.test(el.dataset.path))state.cases[Number(el.dataset.path.split('.')[1])].human={};save();if($('[data-output-count]')&&el.dataset.path.endsWith('.output'))$('[data-output-count]').textContent=n(el.value.trim().split(/\s+/u).filter(Boolean).length)+' '+t('words','کلمه');if($('[data-build-flow]'))$('[data-build-flow]').dataset.ready=String(!!state.goal.trim()&&!!ccase().output.trim());if(editing!==null&&el.dataset.path.endsWith('.name')){const b=$$('[data-edit]')[editing];if(b)b.childNodes[0].textContent=el.value;const names=$$('.mini-rule>b');if(names[editing])names[editing].textContent=el.value;}});
