 $$('[data-method]').forEach(el=>el.onclick=()=>{const c=state.criteria[editing];c.method=el.dataset.method;state.cases.forEach(s=>delete s.human[c.id]);if(c.method==='max_words'&&!/^\d+$/.test(c.rule))c.rule='40';save();render();$('.ev-advanced').open=true;});
 $$('[data-percent]').forEach(el=>el.oninput=()=>{const value=Number(el.value);if(el.dataset.percent==='demo')demoRating=value;else{ccase().human[el.dataset.percent]=value;ccase().result=null;clearDisplayedResult();revision++;persist();}const box=el.closest('.percent-rating');box.dataset.tone=scoreTone(value);$('.score-readout',box).innerHTML=n(value)+`<small> / ${n(100)}</small>`;$('.score-status',box).textContent=value>=Number(el.dataset.pass)?t('Pass','قبول'):t('Needs work','نیاز به اصلاح');$('.percent-mood',box).innerHTML=face(moods[value<25?0:value<50?1:value<75?2:3]);el.setAttribute('aria-valuetext',`${n(value)} ${t('out of 100','از ۱۰۰')}`);if(el.dataset.percent==='demo')$$('[data-anchor]').forEach(b=>b.setAttribute('aria-pressed',String(Math.floor(Math.min(value,99)/25)===Math.floor(Number(b.dataset.anchor)/25))));});
 $$('[data-threshold]').forEach(el=>el.oninput=()=>{state.threshold=Number(el.value);save();});
 $$('[data-criterion-threshold]').forEach(el=>el.oninput=()=>{state.criteria[Number(el.dataset.criterionThreshold)].threshold=Number(el.value);save();});
 $$('[data-rating]').forEach(el=>el.onclick=()=>{const value=Number(el.dataset.value);if(el.dataset.rating==='demo'){demoRating=value;}else{ccase().human[el.dataset.rating]=value;ccase().result=null;revision++;persist();}render();});
 $$('[data-weight]').forEach(el=>el.onclick=()=>{const index=Number(el.dataset.weight);state.criteria[index].weight=Number(el.dataset.value);save();$$('[data-weight]').filter(b=>b.dataset.weight===el.dataset.weight).forEach(b=>b.setAttribute('aria-pressed',b===el?'true':'false'));$('.importance-bars').children[index].style.flex=el.dataset.value;$$('.importance-bars>span').forEach((bar,i)=>bar.textContent=n(Math.round(state.criteria[i].weight/state.criteria.reduce((sum,c)=>sum+c.weight,0)*100))+'٪');});
 $$('[data-required]').forEach(el=>el.onclick=()=>{const c=state.criteria[Number(el.dataset.required)];c.required=!c.required;save();el.setAttribute('aria-checked',String(c.required));});
 $$('[data-case]').forEach(el=>el.onclick=()=>{caseIndex=Number(el.dataset.case);render();});
 if($('#add-test'))$('#add-test').onclick=()=>{state.cases.push(sample('جواب من','',''));caseIndex=state.cases.length-1;save();render();$$('.evidence-details')[1].open=true;};
 $$('[data-stage]').forEach(el=>el.onclick=()=>{ccase().stage=el.dataset.stage;ccase().human={};save();render();$$('.evidence-details')[1].open=true;});
